(() => {
      const f = window.npcTest;
      if (!f?.ready || f.app.npcs.npcs.length !== 3) throw new Error('NPC inspection not ready');
      f.freeze(true); f.app.dev.freeze(true); f.debug(true); f.neutral(true); f.step(0);
      return f.stats();
    })()

